      "name": "analyticOrderAt_neg",
      "module_name": "Mathlib.Analysis.Analytic.Order",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} {E : Type u_2} [inst : NontriviallyNormedField 𝕜] [inst_1 : NormedAddCommGroup E]\n  [inst_2 : NormedSpace 𝕜 E] {f : 𝕜 → E} {z₀ : 𝕜}, analyticOrderAt (-f) z₀ = analyticOrderAt f z₀"
    },
    {
      "name": "multiplicity_neg",
      "module_name": "Mathlib.RingTheory.Multiplicity",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : Ring α] (a b : α), multiplicity a (-b) = multiplicity a b"
    },
    {
      "name": "MvPolynomial.degrees_neg",
      "module_name": "Mathlib.Algebra.MvPolynomial.CommRing",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommRing R] (p : MvPolynomial σ R), (-p).degrees = p.degrees"
    },
    {
      "name": "analyticOrderAt",
      "module_name": "Mathlib.Analysis.Analytic.Order",
      "kind": "definition",
      "type": "{𝕜 : Type u_1} →\n  {E : Type u_2} →\n    [inst : NontriviallyNormedField 𝕜] → [inst_1 : NormedAddCommGroup E] → [NormedSpace 𝕜 E] → (𝕜 → E) → 𝕜 → ℕ∞"
    },
    {
      "name": "PowerSeries.order_neg",
      "module_name": "Mathlib.RingTheory.PowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : Ring R] (φ : PowerSeries R), (-φ).order = φ.order"
    },
    {
      "name": "Polynomial.natTrailingDegree_neg",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.TrailingDegree",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] (p : Polynomial R), (-p).natTrailingDegree = p.natTrailingDegree"
    }
  ]
}
